// Oeste ProfileStatus — Mesa theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Mesa tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/mesa/src/index.js
// Docs: https://oeste.hiddeninwest.com/mesa/#/components/profile-status

const MONO = "font-[ui-monospace,'SF_Mono','Cascadia_Code',Menlo,Consolas,monospace]";

export function ProfileStatus({ children }) {
  return (
    <span className={`${MONO} mt-2 inline-block rounded-full border border-[#8a1f2b] px-[9px] py-[3px] text-[11px] font-bold uppercase tracking-[0.08em] text-[#6d1620] dark:border-[#c9404f] dark:text-[#c9404f]`}>{children}</span>
  );
}
